from datetime import date, timedelta

class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books = {}  # book_id -> {'available': bool, 'borrowed_by': str, 'borrowed_on': date}
        self.users = {}  # user -> {'current_book': str, 'fines': float, 'borrow_history': list of (book_id, borrow_date, return_date, fine)}

    def add_book(self, book_id: str) -> None:
        if book_id not in self.books:
            self.books[book_id] = {
                'available': True,
                'borrowed_by': None,
                'borrowed_on': None
            }

    def borrow(self, user: str, book_id: str, day: date) -> None:
        # Check if book exists
        if book_id not in self.books:
            raise ValueError(f"Book {book_id} does not exist")

        # Check if book is available
        if not self.books[book_id]['available']:
            raise ValueError(f"Book {book_id} is already borrowed")

        # Check if user has unpaid fines and already has a book
        if user in self.users and self.users[user]['fines'] > 0:
            if self.users[user].get('current_book') is not None:
                raise ValueError(f"User {user} has unpaid fines and already holds a book")

        # Update book status
        self.books[book_id]['available'] = False
        self.books[book_id]['borrowed_by'] = user
        self.books[book_id]['borrowed_on'] = day

        # Update user status
        if user not in self.users:
            self.users[user] = {'current_book': book_id, 'fines': 0.0, 'borrow_history': []}
        else:
            self.users[user]['current_book'] = book_id

    def return_book(self, user: str, book_id: str, day: date) -> float:
        # Check if book exists
        if book_id not in self.books:
            raise ValueError(f"Book {book_id} does not exist")

        # Check if user borrowed this book
        if (self.books[book_id]['borrowed_by'] != user or 
            self.books[book_id]['available']):
            raise ValueError(f"User {user} did not borrow book {book_id}")

        # Calculate fine
        borrow_date = self.books[book_id]['borrowed_on']
        due_date = self._calculate_due_date(borrow_date)
        fine = 0.0

        # Calculate days overdue (excluding weekends)
        if day > due_date:
            # Count business days between due_date + 1 and day (inclusive)
            overdue_days = 0
            current = due_date + timedelta(days=1)
            while current <= day:
                if current.weekday() < 5:  # Monday=0, Sunday=6, so 0-4 are weekdays
                    overdue_days += 1
                current += timedelta(days=1)
            fine = overdue_days * self.daily_fine

        # Update book status
        self.books[book_id]['available'] = True
        self.books[book_id]['borrowed_by'] = None
        self.books[book_id]['borrowed_on'] = None

        # Update user status
        if user in self.users:
            # Remove current book reference
            if self.users[user].get('current_book') == book_id:
                self.users[user]['current_book'] = None

            # Add to history
            self.users[user]['borrow_history'].append((book_id, borrow_date, day, fine))
            self.users[user]['fines'] += fine

        return fine

    def _calculate_due_date(self, borrow_date: date) -> date:
        """Calculate due date by adding loan_days, skipping weekends"""
        due_date = borrow_date
        days_added = 0
        while days_added < self.loan_days:
            due_date += timedelta(days=1)
            if due_date.weekday() < 5:  # Only count weekdays
                days_added += 1
        return due_date

    def unpaid_fines(self, user: str) -> float:
        if user not in self.users:
            return 0.0
        return self.users[user]['fines']

    def pay(self, user: str) -> None:
        if user in self.users:
            self.users[user]['fines'] = 0.0
